using DAL;
using Microsoft.Extensions.DependencyInjection;
using Utils.Interface;
namespace Tests;
public class AdminOrdersTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Admin_order_read_filters_IST_dates_shipping_phone_and_detail()
    {
        var admin=await Admin();var buyer=await LoginPhone("9890000091","Synthetic Orders Buyer");using var scope=Factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<IMySqlDapperHelper>();var data=scope.ServiceProvider.GetRequiredService<OrdersDAL>();var ids=new[]{Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid()};var start=new DateTime(2026,11,23,18,30,0,DateTimeKind.Utc);
        await using(var tx=await db.BeginAsync()){for(var i=0;i<3;i++)await data.InsertOrderAsync(new(){Id=ids[i],Number="SYNTH-ADMIN-ORDER-"+i,UserId=Guid.Parse(buyer.Id),Status="placed",PaymentMethod="cod",PaymentStatus="cod",ShipTo="{\"phone\":\"9876543210\"}",ItemsTotal=12345,GrandTotal=12345,Currency="INR",FxRate=1,Fees="[]",IdempotencyKey=Guid.NewGuid().ToString(),CreatedAt=i==0?start.AddSeconds(-1):i==1?start:start.AddDays(1),UpdatedAt=start},tx);await tx.CommitAsync();}
        Assert.Equal(403,(await buyer.Get("/api/admin/orders")).Status);Assert.Equal(403,(await buyer.Get("/api/admin/orders/"+ids[1])).Status);var r=await admin.Get("/api/admin/orders?date_from=2026-11-24&date_to=2026-11-24");Assert.True(r.Status==200,r.ToString());Assert.Single(r.Json["items"]!.AsArray());Assert.Equal(ids[1].ToString(),r.Json["items"]![0]!["id"]!.GetValue<string>());Assert.Equal("Synthetic Orders Buyer",r.Json["items"]![0]!["customer"]!.GetValue<string>());Assert.Empty(r.Json["items"]![0]!["package_statuses"]!.AsArray());
        Assert.Equal(3,(await admin.Get("/api/admin/orders?q="+Uri.EscapeDataString("+91 98765-43210"))).Json["total"]!.GetValue<int>());Assert.Single((await admin.Get("/api/admin/orders?q=%20ORDER-1%20&customer_id="+buyer.Id+"&payment_method=cod&payment_status=cod&status=placed")).Json["items"]!.AsArray());Assert.Empty((await admin.Get("/api/admin/orders?payment_status=paid")).Json["items"]!.AsArray());Assert.Empty((await admin.Get("/api/admin/orders?package_status=packed")).Json["items"]!.AsArray());Assert.Empty((await admin.Get("/api/admin/orders?seller_id="+Guid.NewGuid())).Json["items"]!.AsArray());Assert.Single((await admin.Get("/api/admin/orders?page_size=2&page=2")).Json["items"]!.AsArray());
        Assert.Equal("invalid_date",(await admin.Get("/api/admin/orders?date_from=2026-02-30")).ErrorCode);Assert.Equal(422,(await admin.Get("/api/admin/orders?date_from=2026-2-3")).Status);Assert.Equal(422,(await admin.Get("/api/admin/orders?payment_status=bogus")).Status);Assert.Equal(422,(await admin.Get("/api/admin/orders?page=0")).Status);
        var seller=await LoginPhone("9890000092");var sid=(await seller.Post("/api/seller/register",new{display_name="Synthetic Order Store"})).Json["id"]!.GetValue<string>();await using(var tx=await db.BeginAsync()){foreach(var (number,status) in new[]{("PACKAGE-B","packed"),("PACKAGE-A","placed")})await data.InsertSubOrderAsync(new(){Id=Guid.NewGuid(),OrderId=ids[1],SellerId=Guid.Parse(sid),Number=number,Status=status,SettlementStatus="pending",TrackingNumber="SYNTH-AWB-7788",CreatedAt=start,UpdatedAt=start},tx);await tx.CommitAsync();}
        r=await admin.Get("/api/admin/orders?package_status=packed&seller_id="+sid);Assert.Single(r.Json["items"]!.AsArray());Assert.Equal(new[]{"placed","packed"},r.Json["items"]![0]!["package_statuses"]!.AsArray().Select(x=>x!.GetValue<string>()));Assert.Single((await admin.Get("/api/admin/orders?q=SYNTH-AWB-7788")).Json["items"]!.AsArray());Assert.Single((await admin.Get("/api/admin/orders?q=PACKAGE-A")).Json["items"]!.AsArray());Assert.Empty((await admin.Get("/api/admin/orders?package_status=delivered&seller_id="+sid)).Json["items"]!.AsArray());
        Assert.Equal(403,(await buyer.Get("/api/admin/orders/"+ids[1]+"/fee-invoice.pdf")).Status);Assert.Equal(404,(await admin.Get("/api/admin/orders/"+ids[1]+"/fee-invoice.pdf")).Status);Assert.Equal(404,(await admin.Get("/api/admin/orders/"+Guid.NewGuid()+"/fee-invoice.pdf")).Status);
        await ApiFactory.DbExecAsync("UPDATE orders SET grand_total=24145,fees_total=11800,fees=@fees,ship_to=@ship,fee_invoice_number='SYNTH/26/000001',fee_invoice_date=@start WHERE id=@id",new{id=ids[1],start,ship="""{"full_name":"Synthetic Buyer","line1":"1 Example Street","line2":"Test Area","city":"Coimbatore","state":"Tamil Nadu","state_code":"33","pincode":"641001","phone":"9876543210"}""",fees="""[{"label":"Synthetic service fee","amount":11800,"taxable":10000,"gst":1800,"gst_bps":1800}]"""});
        using(var client=Factory.CreateClient()){client.DefaultRequestHeaders.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",admin.Token);var pdf=await client.GetAsync("/api/admin/orders/"+ids[1]+"/fee-invoice.pdf");Assert.Equal(System.Net.HttpStatusCode.OK,pdf.StatusCode);Assert.Equal("application/pdf",pdf.Content.Headers.ContentType!.MediaType);Assert.True(pdf.Headers.CacheControl!.Private);Assert.True(pdf.Headers.CacheControl.NoStore);Assert.Equal("inline",pdf.Content.Headers.ContentDisposition!.DispositionType);await File.WriteAllBytesAsync("/tmp/synthetic-admin-feeinvoice49.pdf",await pdf.Content.ReadAsByteArrayAsync());}
        r=await admin.Get("/api/admin/orders/"+ids[1]);Assert.True(r.Status==200,r.ToString());Assert.Equal(buyer.Id,r.Json["customer"]!["id"]!.GetValue<string>());Assert.NotNull(r.Json["refunds"]);Assert.Equal(404,(await admin.Get("/api/admin/orders/"+Guid.NewGuid())).Status);
    }
}
